#include <zephyr/kernel.h>
#include <zephyr/posix/pthread.h>
#include <zephyr/posix/time.h>
#include <zephyr/sys/atomic.h>
#include <zephyr/wait_q.h>

#include <errno.h>
#include <stdbool.h>

#define PTHREAD_STACK_SIZE_DEFAULT 1024

/*
 * Pthread key management
 */
struct pthread_key {
    bool used;
    void (*destructor)(void *);
};

static struct pthread_key keys[CONFIG_PTHREAD_KEY_MAX];
static K_MUTEX_DEFINE(key_mutex);

int pthread_key_create(pthread_key_t *key, void (*destructor)(void *))
{
    int ret = 0;

    k_mutex_lock(&key_mutex, K_FOREVER);

    for (int i = 0; i < CONFIG_PTHREAD_KEY_MAX; i++) {
        if (!keys[i].used) {
            keys[i].used = true;
            keys[i].destructor = destructor;
            *key = i;
            goto out;
        }
    }

    ret = EAGAIN;

out:
    k_mutex_unlock(&key_mutex);
    return ret;
}

int pthread_key_delete(pthread_key_t key)
{
    int ret = 0;

    k_mutex_lock(&key_mutex, K_FOREVER);

    if (key >= CONFIG_PTHREAD_KEY_MAX || !keys[key].used) {
        ret = EINVAL;
        goto out;
    }

    /*
     * POSIX states: "No destructor functions are invoked by
     * pthread_key_delete()."
     * The destructor functions are invoked when a thread exits, for
     * any thread-specific data that has been set for the key.
     *
     * We simply mark the key as unused and clear its destructor.
     * The thread exit cleanup will then correctly skip calling the
     * destructor for this key.
     */
    keys[key].used = false;
    keys[key].destructor = NULL;

out:
    k_mutex_unlock(&key_mutex);
    return ret;
}

int pthread_setspecific(pthread_key_t key, const void *value)
{
    struct k_thread *thread = k_current_get();

    if (key >= CONFIG_PTHREAD_KEY_MAX || !keys[key].used) {
        return EINVAL;
    }

    if (thread->posix_key_data == NULL) {
        thread->posix_key_data = k_calloc(CONFIG_PTHREAD_KEY_MAX, sizeof(void *));
        if (thread->posix_key_data == NULL) {
            return ENOMEM;
        }
    }

    thread->posix_key_data[key] = (void *)value;

    return 0;
}

void *pthread_getspecific(pthread_key_t key)
{
    struct k_thread *thread = k_current_get();

    if (key >= CONFIG_PTHREAD_KEY_MAX || !keys[key].used ||
        thread->posix_key_data == NULL) {
        return NULL;
    }

    return thread->posix_key_data[key];
}

/*
 * Pthread cleanup for thread-specific data (TSD)
 * This function is called when a thread exits.
 */
void pthread_cleanup_tsd(struct k_thread *thread)
{
    if (thread->posix_key_data == NULL) {
        return;
    }

    for (int i = 0; i < CONFIG_PTHREAD_KEY_MAX; i++) {
        /*
         * Only call destructor if:
         * 1. The key is currently in use (not deleted).
         * 2. A destructor function was registered for this key.
         * 3. The thread has set data for this key.
         */
        if (keys[i].used && keys[i].destructor != NULL &&
            thread->posix_key_data[i] != NULL) {
            keys[i].destructor(thread->posix_key_data[i]);
        }
    }

    k_free(thread->posix_key_data);
    thread->posix_key_data = NULL;
}

/*
 * Pthread mutex management
 */
int pthread_mutex_init(pthread_mutex_t *mutex,
                       const pthread_mutexattr_t *attr)
{
    if (mutex == NULL) {
        return EINVAL;
    }

    if (attr != NULL && *attr != PTHREAD_MUTEX_NORMAL &&
        *attr != PTHREAD_MUTEX_RECURSIVE &&
        *attr != PTHREAD_MUTEX_ERRORCHECK) {
        return EINVAL;
    }

    k_mutex_init(&mutex->lock);
    mutex->type = (attr == NULL) ? PTHREAD_MUTEX_NORMAL : *attr;
    mutex->owner = NULL;
    mutex->count = 0;

    return 0;
}

int pthread_mutex_destroy(pthread_mutex_t *mutex)
{
    if (mutex == NULL) {
        return EINVAL;
    }

    /* Zephyr's k_mutex_destroy is a NOP, so we just clear state */
    mutex->owner = NULL;
    mutex->count = 0;
    mutex->type = 0; /* Mark as uninitialized */

    return 0;
}

static int do_mutex_lock(pthread_mutex_t *mutex, k_timeout_t timeout)
{
    struct k_thread *current_thread = k_current_get();
    int ret;

    if (mutex->owner == current_thread) {
        if (mutex->type == PTHREAD_MUTEX_NORMAL) {
            return EDEADLK;
        } else if (mutex->type == PTHREAD_MUTEX_RECURSIVE ||
                   mutex->type == PTHREAD_MUTEX_ERRORCHECK) {
            mutex->count++;
            return 0;
        }
    }

    ret = k_mutex_lock(&mutex->lock, timeout);

    if (ret == 0) {
        mutex->owner = current_thread;
        mutex->count = 1;
    } else if (ret == -EAGAIN) {
        return ETIMEDOUT;
    } else if (ret == -EINVAL) {
        return EINVAL;
    } else {
        return EBUSY; /* Should not happen for k_mutex_lock */
    }

    return 0;
}

int pthread_mutex_lock(pthread_mutex_t *mutex)
{
    if (mutex == NULL) {
        return EINVAL;
    }
    return do_mutex_lock(mutex, K_FOREVER);
}

int pthread_mutex_trylock(pthread_mutex_t *mutex)
{
    if (mutex == NULL) {
        return EINVAL;
    }
    return do_mutex_lock(mutex, K_NO_WAIT);
}

int pthread_mutex_unlock(pthread_mutex_t *mutex)
{
    struct k_thread *current_thread = k_current_get();

    if (mutex == NULL) {
        return EINVAL;
    }

    if (mutex->owner != current_thread) {
        if (mutex->type == PTHREAD_MUTEX_ERRORCHECK) {
            return EPERM;
        } else {
            /* POSIX says undefined behavior for NORMAL/RECURSIVE */
            return EPERM; /* Or some other error, or just proceed */
        }
    }

    if (mutex->type == PTHREAD_MUTEX_RECURSIVE ||
        mutex->type == PTHREAD_MUTEX_ERRORCHECK) {
        mutex->count--;
        if (mutex->count > 0) {
            return 0;
        }
    }

    mutex->owner = NULL;
    return k_mutex_unlock(&mutex->lock);
}

int pthread_mutexattr_init(pthread_mutexattr_t *attr)
{
    if (attr == NULL) {
        return EINVAL;
    }
    *attr = PTHREAD_MUTEX_NORMAL;
    return 0;
}

int pthread_mutexattr_destroy(pthread_mutexattr_t *attr)
{
    if (attr == NULL) {
        return EINVAL;
    }
    /* No resources to free */
    return 0;
}

int pthread_mutexattr_settype(pthread_mutexattr_t *attr, int type)
{
    if (attr == NULL) {
        return EINVAL;
    }
    if (type != PTHREAD_MUTEX_NORMAL &&
        type != PTHREAD_MUTEX_RECURSIVE &&
        type != PTHREAD_MUTEX_ERRORCHECK) {
        return EINVAL;
    }
    *attr = type;
    return 0;
}

int pthread_mutexattr_gettype(const pthread_mutexattr_t *attr, int *type)
{
    if (attr == NULL || type == NULL) {
        return EINVAL;
    }
    *type = *attr;
    return 0;
}

/*
 * Pthread condition variable management
 */
int pthread_cond_init(pthread_cond_t *cond,
                      const pthread_condattr_t *attr)
{
    if (cond == NULL) {
        return EINVAL;
    }

    if (attr != NULL && *attr != PTHREAD_PROCESS_PRIVATE) {
        return EINVAL;
    }

    k_condvar_init(&cond->condvar);
    return 0;
}

int pthread_cond_destroy(pthread_cond_t *cond)
{
    if (cond == NULL) {
        return EINVAL;
    }
    /* Zephyr's k_condvar_destroy is a NOP, so nothing to do */
    return 0;
}

int pthread_cond_signal(pthread_cond_t *cond)
{
    if (cond == NULL) {
        return EINVAL;
    }
    k_condvar_signal(&cond->condvar);
    return 0;
}

int pthread_cond_broadcast(pthread_cond_t *cond)
{
    if (cond == NULL) {
        return EINVAL;
    }
    k_condvar_broadcast(&cond->condvar);
    return 0;
}

static int do_cond_wait(pthread_cond_t *cond, pthread_mutex_t *mutex,
                        k_timeout_t timeout)
{
    int ret;

    if (cond == NULL || mutex == NULL) {
        return EINVAL;
    }

    if (mutex->owner != k_current_get() || mutex->count == 0) {
        /* Mutex must be locked by the calling thread */
        return EPERM;
    }

    /* Unlock the mutex, wait, then re-lock */
    int saved_count = mutex->count;
    mutex->owner = NULL;
    mutex->count = 0;
    k_mutex_unlock(&mutex->lock);

    ret = k_condvar_wait(&cond->condvar, &mutex->lock, timeout);

    /* Re-lock the mutex and restore count */
    mutex->owner = k_current_get();
    mutex->count = saved_count;

    if (ret == -EAGAIN) {
        return ETIMEDOUT;
    } else if (ret == -EINVAL) {
        return EINVAL;
    } else if (ret != 0) {
        /* Other errors from k_condvar_wait */
        return EBUSY; /* Generic error */
    }

    return 0;
}

int pthread_cond_wait(pthread_cond_t *cond, pthread_mutex_t *mutex)
{
    return do_cond_wait(cond, mutex, K_FOREVER);
}

int pthread_cond_timedwait(pthread_cond_t *cond, pthread_mutex_t *mutex,
                           const struct timespec *abstime)
{
    if (abstime == NULL) {
        return EINVAL;
    }

    k_timeout_t timeout = K_FOREVER;
    struct timespec current_time;
    int ret;

    ret = clock_gettime(CLOCK_REALTIME, &current_time);
    if (ret != 0) {
        return ret; /* errno is set by clock_gettime */
    }

    if (abstime->tv_sec < current_time.tv_sec ||
        (abstime->tv_sec == current_time.tv_sec &&
         abstime->tv_nsec <= current_time.tv_nsec)) {
        /* Timeout has already expired or is zero */
        return ETIMEDOUT;
    }

    long long diff_ms = (long long)(abstime->tv_sec - current_time.tv_sec) * 1000LL +
                        (abstime->tv_nsec - current_time.tv_nsec) / 1000000LL;

    if (diff_ms < 0) { /* Should not happen with above check, but for safety */
        diff_ms = 0;
    }

    timeout = K_MSEC(diff_ms);

    return do_cond_wait(cond, mutex, timeout);
}

int pthread_condattr_init(pthread_condattr_t *attr)
{
    if (attr == NULL) {
        return EINVAL;
    }
    *attr = PTHREAD_PROCESS_PRIVATE; /* Only supported type */
    return 0;
}

int pthread_condattr_destroy(pthread_condattr_t *attr)
{
    if (attr == NULL) {
        return EINVAL;
    }
    /* No resources to free */
    return 0;
}

int pthread_condattr_setpshared(pthread_condattr_t *attr, int pshared)
{
    if (attr == NULL) {
        return EINVAL;
    }
    if (pshared != PTHREAD_PROCESS_PRIVATE) {
        return EINVAL; /* Only PTHREAD_PROCESS_PRIVATE is supported */
    }
    *attr = pshared;
    return 0;
}

int pthread_condattr_getpshared(const pthread_condattr_t *attr, int *pshared)
{
    if (attr == NULL || pshared == NULL) {
        return EINVAL;
    }
    *pshared = *attr;
    return 0;
}

/*
 * Pthread thread management
 */
static void pthread_wrapper(void *p1, void *p2, void *p3)
{
    pthread_t *thread_id = (pthread_t *)p1;
    void *(*start_routine)(void *) = (void *(*)(void *))p2;
    void *arg = p3;

    /* Store the return value of the start routine */
    thread_id->retval = start_routine(arg);

    /* Mark thread as exited */
    atomic_set(&thread_id->state, PTHREAD_STATE_EXITED);

    /* Cleanup TSD */
    pthread_cleanup_tsd(k_current_get());

    /* Signal any joiners */
    k_sem_give(&thread_id->join_sem);

    /* If detached, free stack now */
    if (thread_id->detach_state == PTHREAD_CREATE_DETACHED && thread_id->stack_allocated) {
        k_free(thread_id->stack);
        thread_id->stack = NULL;
        thread_id->stack_allocated = false;
    }
}

int pthread_create(pthread_t *thread, const pthread_attr_t *attr,
                   void *(*start_routine)(void *), void *arg)
{
    if (thread == NULL || start_routine == NULL) {
        return EINVAL;
    }

    /* Initialize pthread_t structure */
    thread->stack_size = PTHREAD_STACK_SIZE_DEFAULT;
    thread->priority = K_PRIO_PREEMPT(0); /* Default to highest preemptive */
    thread->detach_state = PTHREAD_CREATE_JOINABLE;
    thread->retval = NULL;
    atomic_set(&thread->state, PTHREAD_STATE_RUNNING);
    k_sem_init(&thread->join_sem, 0, 1); /* Binary semaphore for join */

    if (attr != NULL) {
        thread->stack_size = attr->stack_size;
        thread->priority = attr->priority;
        thread->detach_state = attr->detach_state;
    }

    /* Allocate stack if not provided by attr */
    if (attr == NULL || attr->stack == NULL) {
        thread->stack = k_malloc(thread->stack_size);
        if (thread->stack == NULL) {
            return ENOMEM;
        }
        thread->stack_allocated = true;
    } else {
        thread->stack = attr->stack;
        thread->stack_allocated = false;
    }

    k_thread_create(&thread->thread, thread->stack, thread->stack_size,
                    pthread_wrapper, thread, (void *)start_routine, arg,
                    thread->priority, 0, K_NO_WAIT);

    k_thread_name_set(&thread->thread, "pthread");

    return 0;
}

void pthread_exit(void *retval)
{
    pthread_t *thread_id = (pthread_t *)k_current_get()->base.user_data;

    if (thread_id != NULL) {
        thread_id->retval = retval;
        atomic_set(&thread_id->state, PTHREAD_STATE_EXITED);
        k_sem_give(&thread_id->join_sem);

        /* If detached, free stack now */
        if (thread_id->detach_state == PTHREAD_CREATE_DETACHED && thread_id->stack_allocated) {
            k_free(thread_id->stack);
            thread_id->stack = NULL;
            thread_id->stack_allocated = false;
        }
    }

    /* Cleanup TSD */
    pthread_cleanup_tsd(k_current_get());

    k_thread_abort(k_current_get());
}

int pthread_join(pthread_t *thread, void **retval)
{
    if (atomic_get(&thread->state) == PTHREAD_STATE_DETACHED) {
        return EINVAL; /* Cannot join a detached thread */
    }

    if (k_current_get() == &thread->thread) {
        return EDEADLK; /* Cannot join self */
    }

    /* Wait for the thread to exit */
    k_sem_take(&thread->join_sem, K_FOREVER);

    if (retval != NULL) {
        *retval = thread->retval;
    }

    /* Free resources if stack was allocated by pthread_create */
    if (thread->stack_allocated) {
        k_free(thread->stack);
        thread->stack = NULL;
        thread->stack_allocated = false;
    }

    return 0;
}

int pthread_detach(pthread_t *thread)
{
    if (atomic_get(&thread->state) == PTHREAD_STATE_DETACHED) {
        return EINVAL; /* Already detached */
    }

    atomic_set(&thread->state, PTHREAD_STATE_DETACHED);

    /* If the thread has already exited, free resources now */
    if (atomic_get(&thread->state) == PTHREAD_STATE_EXITED) {
        if (thread->stack_allocated) {
            k_free(thread->stack);
            thread->stack = NULL;
            thread->stack_allocated = false;
        }
    }
    /* If not exited, resources will be freed by pthread_wrapper or pthread_exit */

    return 0;
}

pthread_t pthread_self(void)
{
    /* This is a bit tricky. Zephyr's k_thread doesn't directly map to pthread_t.
     * We assume pthread_t is embedded in k_thread's user_data or similar.
     * For now, return a dummy or the k_thread pointer itself.
     * A proper implementation would require k_thread to store a pointer to its
     * pthread_t wrapper.
     */
    return *(pthread_t *)k_current_get()->base.user_data;
}

int pthread_equal(pthread_t t1, pthread_t t2)
{
    return (t1.thread.base.user_data == t2.thread.base.user_data);
}

/*
 * Pthread attribute management
 */
int pthread_attr_init(pthread_attr_t *attr)
{
    if (attr == NULL) {
        return EINVAL;
    }
    attr->stack = NULL;
    attr->stack_size = PTHREAD_STACK_SIZE_DEFAULT;
    attr->priority = K_PRIO_PREEMPT(0);
    attr->detach_state = PTHREAD_CREATE_JOINABLE;
    return 0;
}

int pthread_attr_destroy(pthread_attr_t *attr)
{
    if (attr == NULL) {
        return EINVAL;
    }
    /* No resources to free */
    return 0;
}

int pthread_attr_setstacksize(pthread_attr_t *attr, size_t stacksize)
{
    if (attr == NULL || stacksize == 0) {
        return EINVAL;
    }
    attr->stack_size = stacksize;
    return 0;
}

int pthread_attr_getstacksize(const pthread_attr_t *attr, size_t *stacksize)
{
    if (attr == NULL || stacksize == NULL) {
        return EINVAL;
    }
    *stacksize = attr->stack_size;
    return 0;
}

int pthread_attr_setstack(pthread_attr_t *attr, void *stackaddr,
                          size_t stacksize)
{
    if (attr == NULL || stackaddr == NULL || stacksize == 0) {
        return EINVAL;
    }
    attr->stack = stackaddr;
    attr->stack_size = stacksize;
    return 0;
}

int pthread_attr_getstack(const pthread_attr_t *attr, void **stackaddr,
                          size_t *stacksize)
{
    if (attr == NULL || stackaddr == NULL || stacksize == NULL) {
        return EINVAL;
    }
    *stackaddr = attr->stack;
    *stacksize = attr->stack_size;
    return 0;
}

int pthread_attr_setdetachstate(pthread_attr_t *attr, int detachstate)
{
    if (attr == NULL) {
        return EINVAL;
    }
    if (detachstate != PTHREAD_CREATE_JOINABLE &&
        detachstate != PTHREAD_CREATE_DETACHED) {
        return EINVAL;
    }
    attr->detach_state = detachstate;
    return 0;
}

int pthread_attr_getdetachstate(const pthread_attr_t *attr, int *detachstate)
{
    if (attr == NULL || detachstate == NULL) {
        return EINVAL;
    }
    *detachstate = attr->detach_state;
    return 0;
}

int pthread_attr_setschedparam(pthread_attr_t *attr,
                               const struct sched_param *param)
{
    if (attr == NULL || param == NULL) {
        return EINVAL;
    }
    attr->priority = param->sched_priority;
    return 0;
}

int pthread_attr_getschedparam(const pthread_attr_t *attr,
                               struct sched_param *param)
{
    if (attr == NULL || param == NULL) {
        return EINVAL;
    }
    param->sched_priority = attr->priority;
    return 0;
}

int pthread_attr_setschedpolicy(pthread_attr_t *attr, int policy)
{
    if (attr == NULL) {
        return EINVAL;
    }
    /* Zephyr only supports SCHED_FIFO for now */
    if (policy != SCHED_FIFO) {
        return EINVAL;
    }
    attr->policy = policy;
    return 0;
}

int pthread_attr_getschedpolicy(const pthread_attr_t *attr, int *policy)
{
    if (attr == NULL || policy == NULL) {
        return EINVAL;
    }
    *policy = attr->policy;
    return 0;
}

int pthread_attr_setinheritsched(pthread_attr_t *attr, int inheritsched)
{
    if (attr == NULL) {
        return EINVAL;
    }
    /* Zephyr does not support inheritsched */
    if (inheritsched != PTHREAD_EXPLICIT_SCHED) {
        return EINVAL;
    }
    attr->inheritsched = inheritsched;
    return 0;
}

int pthread_attr_getinheritsched(const pthread_attr_t *attr, int *inheritsched)
{
    if (attr == NULL || inheritsched == NULL) {
        return EINVAL;
    }
    *inheritsched = attr->inheritsched;
    return 0;
}

int pthread_attr_setscope(pthread_attr_t *attr, int scope)
{
    if (attr == NULL) {
        return EINVAL;
    }
    /* Zephyr only supports PTHREAD_SCOPE_SYSTEM */
    if (scope != PTHREAD_SCOPE_SYSTEM) {
        return EINVAL;
    }
    attr->scope = scope;
    return 0;
}

int pthread_attr_getscope(const pthread_attr_t *attr, int *scope)
{
    if (attr == NULL || scope == NULL) {
        return EINVAL;
    }
    *scope = attr->scope;
    return 0;
}

/*
 * Pthread once management
 */
int pthread_once(pthread_once_t *once_control, void (*init_routine)(void))
{
    if (once_control == NULL || init_routine == NULL) {
        return EINVAL;
    }

    if (atomic_cas(once_control, PTHREAD_ONCE_INIT, PTHREAD_ONCE_RUNNING)) {
        init_routine();
        atomic_set(once_control, PTHREAD_ONCE_DONE);
    } else {
        /* Wait for the routine to complete if another thread is running it */
        while (atomic_get(once_control) == PTHREAD_ONCE_RUNNING) {
            k_yield(); /* Or use a proper wait mechanism */
        }
    }

    return 0;
}
